import{_ as s,C as t,c as n,o as r,aa as l,G as a}from"./chunks/framework.Cn7WEiMX.js";const f=JSON.parse('{"title":"存储安装","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/Dynmap/setup/storage-setup/index.md","filePath":"wiki/Dynmap/setup/storage-setup/index.md"}'),p={name:"wiki/Dynmap/setup/storage-setup/index.md"};function _(c,e,d,m,u,S){const o=t("NolebaseGitContributors"),i=t("NolebaseGitChangelog");return r(),n("div",null,[e[0]||(e[0]=l('<h1 id="存储安装" tabindex="-1">存储安装 <a class="header-anchor" href="#存储安装" aria-label="Permalink to &quot;存储安装&quot;">​</a></h1> <p>Dynmap 需要大量空间存储地图图块、标记点等数据。默认情况下，存储功能由本地文件系统提供，另外支持其他的存储方法。目前插件支持如下：</p> <ul><li>文件系统存储 - 默认选项，最简单的选择。</li> <li>MySQL/MariaDB 存储 - 使用 MySQL 或 MariaDB 数据库存储地图数据。可以带来一些优势 - 允许网页服务器与 MC 服务器分离，架设在不同的电脑/虚拟机/容器中。</li> <li>PostgreSQL 存储 - 使用 PostgreSQL 数据库存储地图数据。可以带来一些优势 - 允许网页服务器与 MC 服务器分离，架设在不同的电脑/虚拟机/容器中。</li> <li>SQLite 存储 - 使用最简单的 SQLite 数据库存储地图数据。与文件系统存储类型（本地运行，且与 Minecraft 进程绑定），但可以降低单文件的占用。</li> <li>AWS S3 对象存储 - 既可以用作存储，也可以用作外置网页服务器，允许地图数据在 AWS S3“存储桶”中的推送及拉取，适用于需要大型本地存储和/或额外内置网页服务器 TCP/IP 端口，却受限于托管环境而无法获得的服务器。</li></ul> ',6)),a(o),a(i)])}const g=s(p,[["render",_]]);export{f as __pageData,g as default};
